<?php
defined( 'ABSPATH' ) || exit;
class AMANAH_SEO_AI_Generation_Requirements {
 const DIMENSIONS=array('Content Identity','Search Intent Satisfaction','Topic Coverage','Content Completeness','Factual Integrity','Entity & Context','Article Structure','Readability & User Experience','Semantic SEO','Value & Differentiation','FAQ Quality','AI/Search Readiness');
 const TYPES=array('must_improve','must_cover','must_answer','must_preserve','must_avoid','recommended_direction');
 const DISPOSITIONS=array('mandatory','recommended','informational','human_review');
 const SEVERITIES=array('CRITICAL','HIGH','MEDIUM','LOW','INFORMATIONAL','UNKNOWN/UNASSESSED');
 public static function normalize(array $requirements){$out=array();foreach(self::TYPES as $type){$items=isset($requirements[$type])&&is_array($requirements[$type])?$requirements[$type]:array();$out[$type]=array();foreach($items as $item){if(!is_array($item))continue;$statement=isset($item['statement'])?sanitize_textarea_field($item['statement']):'';if(''===$statement)continue;$dimension=isset($item['quality_dimension'])?sanitize_text_field($item['quality_dimension']):'UNKNOWN/UNASSESSED';if('UNKNOWN/UNASSESSED'!==$dimension&&!in_array($dimension,self::DIMENSIONS,true))$dimension='UNKNOWN/UNASSESSED';$severity=isset($item['severity'])?sanitize_text_field($item['severity']):'UNKNOWN/UNASSESSED';if(!in_array($severity,self::SEVERITIES,true))$severity='UNKNOWN/UNASSESSED';$default_disposition=in_array($type,array('must_improve','must_cover','must_answer','must_avoid'),true)?'mandatory':'recommended';$disposition=isset($item['disposition'])?sanitize_key($item['disposition']):$default_disposition;if(!in_array($disposition,self::DISPOSITIONS,true))$disposition=$default_disposition;$out[$type][]=array('requirement_id'=>isset($item['requirement_id'])?sanitize_key($item['requirement_id']):wp_generate_uuid4(),'source_finding'=>isset($item['source_finding'])?sanitize_text_field($item['source_finding']):'','quality_dimension'=>$dimension,'requirement_type'=>$type,'severity'=>$severity,'statement'=>$statement,'rationale'=>isset($item['rationale'])?sanitize_textarea_field($item['rationale']):'','disposition'=>$disposition);}}return $out;}
}
